command:
set +e
cd /tmp
curl -sL -o ft.tgz https://download.savannah.gnu.org/releases/freetype/freetype-old/freetype-2.4.11.tar.gz && tar xzf ft.tgz && cp -r freetype-2.4.11 freetype-2.4.11-i64
(cd freetype-2.4.11 && ./configure --prefix=/tmp/ftA --without-zlib --without-bzip2 -q >/dev/null 2>&1 && make -j4 -s >/dev/null 2>&1 && make install -s >/dev/null 2>&1) && echo A-ok
(cd freetype-2.4.11-i64 && CFLAGS="-O2 -DFT_CONFIG_OPTION_FORCE_INT64" ./configure --prefix=/tmp/ftB --without-zlib --without-bzip2 -q >/dev/null 2>&1 && make -j4 -s >/dev/null 2>&1 && make install -s >/dev/null 2>&1) && echo B-ok
echo "===== DivFix source (non-LONG64)"
awk '/#else \/\* !FT_LONG64 \*\//{f=1} f' freetype-2.4.11/src/base/ftcalc.c | sed -n '/static FT_UInt32/,/^  }/p;/FT_DivFix( FT_Long/,/^  }/p' | head -150
echo "===== Add64"; sed -n '/FT_Add64( FT_Int64/,/^  }/p' freetype-2.4.11/src/base/ftcalc.c
cat > cmp.c <<'EOF'
#include <ft2build.h>
#include FT_FREETYPE_H
#include FT_TRIGONOMETRY_H
#include <stdio.h>
#include <stdint.h>
static uint64_t h = 1469598103934665603ULL;
static void mix(int64_t v){ h ^= (uint64_t)v; h *= 1099511628211ULL; }
static uint64_t s = 0x9E3779B97F4A7C15ULL;
static uint64_t rnd(void){ s ^= s << 13; s ^= s >> 7; s ^= s << 17; return s; }
int main(int argc, char** argv){
  const char* f = argv[1]; const int64_t full = 360L << 16; int chunk = 0;
  if (f[0]=='s' || f[0]=='c' || f[0]=='t' || f[0]=='u') {
    for (int64_t a = -2*full; a <= 2*full; a++) {
      if (f[0]=='s') mix(FT_Sin(a)); else if (f[0]=='c') mix(FT_Cos(a)); else if (f[0]=='t') mix(FT_Tan(a));
      else { FT_Vector v; FT_Vector_Unit(&v, a); mix(v.x); mix(v.y); }
      if (((a + 2*full) & 0xFFFFF) == 0xFFFFF) printf("%d %016llx\n", chunk++, (unsigned long long)h);
    }
  } else {
    for (int i = 0; i < 20000000; i++) {
      int sh = 1 + (int)(rnd() % 50); int64_t m = (1LL << sh) - 1;
      int64_t x = (int64_t)(rnd() % (2*(uint64_t)m+1)) - m, y = (int64_t)(rnd() % (2*(uint64_t)m+1)) - m;
      int64_t ang = (int64_t)(rnd() % (8*full)) - 4*full;
      FT_Vector v = {x, y};
      if (f[0]=='r') { FT_Vector_Rotate(&v, ang); mix(v.x); mix(v.y); }
      else if (f[0]=='l') { mix(FT_Vector_Length(&v)); }
      else if (f[0]=='p') { FT_Fixed len = 0; FT_Angle an = 0; FT_Vector_Polarize(&v, &len, &an); mix(len); mix(an); }
      else if (f[0]=='a') { mix(FT_Atan2(x, y)); }
      else if (f[0]=='f') { FT_Vector o; FT_Vector_From_Polar(&o, x, ang); mix(o.x); mix(o.y); }
      if (i % 1000000 == 999999) printf("%d %016llx\n", chunk++, (unsigned long long)h);
    }
  }
  return 0;
}
EOF
gcc -O2 -o cmpA cmp.c -I/tmp/ftA/include -I/tmp/ftA/include/freetype2 /tmp/ftA/lib/libfreetype.a -lm
gcc -O2 -o cmpB cmp.c -I/tmp/ftB/include -I/tmp/ftB/include/freetype2 /tmp/ftB/lib/libfreetype.a -lm
for fn in sin cos tan unit rotate length polarize atan from; do ./cmpA $fn > A_$fn & ./cmpB $fn > B_$fn & wait; echo "$fn A-vs-INT64: $(diff A_$fn B_$fn | grep -m1 '^<' || echo identical) ($(wc -l < A_$fn) chunks)"; done

